'use strict';
/*
 * Dashboard UI translations. `config.json`'s `language` governs BOTH the agent's own output (specs,
 * plans, code comments — per AGENTS.md) AND, from here, this dashboard's chrome — so picking a
 * language actually changes what you see, not just what the agent writes.
 *
 * t(key, vars?) looks up I18N[currentLang][key], falls back to I18N.en[key], then to the key itself
 * (so a missing translation never breaks the UI — it just shows English or the raw key). {placeholder}
 * tokens in a string are substituted from `vars`. currentLang is set by i18nSetLang(), called from
 * render() on every tick (app.js) — so language changes apply live, no reload, no separate wiring.
 *
 * applyI18nStatic() walks two attributes on the static markup (index.html):
 *   data-i18n="key"       → element.textContent = t(key)
 *   data-i18n-html="key"  → element.innerHTML = t(key)   (for strings authored with inline <em>/<code>)
 *   data-i18n-ph="key"    → element.placeholder = t(key)
 *   data-i18n-title="key" → element.title = t(key)
 *   data-i18n-aria="key"  → element.setAttribute('aria-label', t(key))
 * It's called once at boot and again at the end of every render() tick.
 */
